"use client";

import { motion } from "framer-motion";
import { Award, Calendar, Hash, School, Globe, FileText, Users, Layers, Download, Share2, CheckCircle, AlertTriangle } from "lucide-react";
import { Button } from "@/components/ui/button";
import { formatDateReadable } from "@/lib/utils";
import Image from "next/image";

type CertificateData = {
  certificate_id: string;
  participant_name: string;
  school: string;
  certificate_type: string;
  event: string | null;
  event_code: string | null;
  date_issued: string;
  status: string;
  pdf_available: boolean;
  pdf_download_url: string | null;
  country?: string;
  committee?: string;
  segment?: string;
  team_name?: string;
  [key: string]: any;
};

interface CertificateDisplayProps {
  certificate: CertificateData;
  valid?: boolean;
  revoked?: boolean;
  revokedInfo?: {
    revoked_at: string;
    revoked_reason: string;
  } | null;
}

export function CertificateDisplay({ certificate, valid = true, revoked = false, revokedInfo }: CertificateDisplayProps) {
  return (
    <motion.div 
      initial={{ opacity: 0, scale: 0.95 }}
      animate={{ opacity: 1, scale: 1 }}
      transition={{ duration: 0.5 }}
      className="relative w-full max-w-4xl mx-auto"
    >
      {/* Certificate Container - Mimicking a physical paper/card */}
      <div className="relative bg-[#0F1B14] border-[8px] border-double border-accent-gold/40 rounded-lg p-8 md:p-12 shadow-2xl overflow-hidden">
        
        {/* Background Texture/Watermark */}
        <div className="absolute inset-0 opacity-5 pointer-events-none flex items-center justify-center">
           {/* You could put a large logo SVG here if available */}
           <Award className="w-96 h-96 text-accent-gold" />
        </div>
        
        {/* Corner Ornaments */}
        <div className="absolute top-4 left-4 w-16 h-16 border-t-2 border-l-2 border-accent-gold/60 rounded-tl-3xl" />
        <div className="absolute top-4 right-4 w-16 h-16 border-t-2 border-r-2 border-accent-gold/60 rounded-tr-3xl" />
        <div className="absolute bottom-4 left-4 w-16 h-16 border-b-2 border-l-2 border-accent-gold/60 rounded-bl-3xl" />
        <div className="absolute bottom-4 right-4 w-16 h-16 border-b-2 border-r-2 border-accent-gold/60 rounded-br-3xl" />

        {/* Header Section */}
        <div className="text-center mb-12 relative z-10">
          <div className="flex justify-center mb-6">
            <div className="relative">
               {/* Logo Placeholder - Replace with actual logo if available */}
               <div className="w-20 h-20 md:w-24 md:h-24 relative">
                  <Image
                    src="/logo.png"
                    alt="IGACMUN Logo"
                    width={96}
                    height={96}
                    className="object-contain w-full h-full drop-shadow-[0_0_15px_rgba(198,168,88,0.3)]"
                  />
               </div>
            </div>
          </div>
          
          <h1 className="font-[family-name:var(--font-cinzel)] text-3xl md:text-5xl font-bold text-accent-gold mb-2 tracking-wide">
            Certificate of {certificate.certificate_type.replace('Certificate of ', '')}
          </h1>
          <p className="text-muted-foreground uppercase tracking-[0.3em] text-xs md:text-sm">
            International Global Affairs Council
          </p>
        </div>

        {/* Main Content */}
        <div className="text-center space-y-8 relative z-10">
          <p className="text-lg md:text-xl text-foreground/80 font-serif italic">
            This is to certify that
          </p>
          
          <div className="py-4 border-b border-accent-gold/30 max-w-2xl mx-auto">
            <h2 className="font-[family-name:var(--font-cinzel)] text-4xl md:text-6xl font-bold text-foreground bg-clip-text text-transparent bg-gradient-to-r from-white via-white to-white/90">
              {certificate.participant_name}
            </h2>
          </div>

          <div className="space-y-4">
            <p className="text-lg md:text-xl text-foreground/80 font-serif italic">
              has successfully participated in
            </p>
            <h3 className="font-[family-name:var(--font-cinzel)] text-2xl md:text-3xl font-bold text-accent-gold">
              {certificate.event || "IGACMUN Session III"}
            </h3>
            
            <div className="flex flex-wrap justify-center gap-x-8 gap-y-2 text-muted-foreground mt-4">
               {certificate.committee && (
                 <span className="flex items-center gap-2">
                   <Users className="w-4 h-4 text-accent-gold" />
                   {certificate.committee}
                 </span>
               )}
               {certificate.school && (
                 <span className="flex items-center gap-2">
                   <School className="w-4 h-4 text-accent-gold" />
                   {certificate.school}
                 </span>
               )}
               {certificate.country && (
                 <span className="flex items-center gap-2">
                   <Globe className="w-4 h-4 text-accent-gold" />
                   {certificate.country}
                 </span>
               )}
            </div>
          </div>
        </div>

        {/* Footer / Verification Details */}
        <div className="mt-16 pt-8 border-t border-accent-gold/20 flex flex-col md:flex-row justify-between items-end gap-8 relative z-10">
          
          {/* Left: Date & ID */}
          <div className="text-left space-y-2">
            <div className="flex items-center gap-2 text-sm text-muted-foreground">
              <Calendar className="w-4 h-4 text-accent-gold" />
              <span>Issued: {formatDateReadable(certificate.date_issued)}</span>
            </div>
            <div className="flex items-center gap-2 text-sm text-muted-foreground">
              <Hash className="w-4 h-4 text-accent-gold" />
              <span className="font-mono">ID: {certificate.certificate_id}</span>
            </div>
          </div>

          {/* Center: Seal (Visual) */}
          <div className="absolute left-1/2 bottom-8 transform -translate-x-1/2 hidden md:block">
             <div className="w-24 h-24 rounded-full border-4 border-accent-gold/40 flex items-center justify-center bg-forest-950/50 backdrop-blur-sm">
                <div className="w-20 h-20 rounded-full border border-accent-gold/60 flex items-center justify-center">
                   <Award className="w-10 h-10 text-accent-gold opacity-80" />
                </div>
             </div>
          </div>

          {/* Right: Status Badge */}
          <div className="text-right">
            {revoked ? (
              <div className="flex items-center gap-2 text-destructive bg-destructive/10 px-4 py-2 rounded-full border border-destructive/30">
                <AlertTriangle className="w-5 h-5" />
                <span className="font-bold uppercase tracking-wider text-sm">Revoked</span>
              </div>
            ) : valid ? (
              <div className="flex items-center gap-2 text-green-400 bg-green-500/10 px-4 py-2 rounded-full border border-green-500/30">
                <CheckCircle className="w-5 h-5" />
                <span className="font-bold uppercase tracking-wider text-sm">Verified</span>
              </div>
            ) : null}
          </div>
        </div>
      </div>

      {/* Action Buttons */}
      <div className="mt-8 flex flex-wrap justify-center gap-4">
        <Button
          onClick={() => {
            navigator.clipboard.writeText(
              `${window.location.origin}/certificate-portal/${certificate.certificate_id}`
            );
            alert("Certificate link copied to clipboard!");
          }}
          variant="outline"
          className="border-accent-gold/30 text-accent-gold hover:bg-accent-gold/10 min-w-[140px]"
        >
          <Share2 className="h-4 w-4 mr-2" />
          Share Link
        </Button>
        
        {certificate.pdf_available && certificate.pdf_download_url && (
          <Button
            onClick={() => window.open(certificate.pdf_download_url!, "_blank")}
            className="bg-accent-gold hover:bg-accent-gold/90 text-forest-950 min-w-[140px]"
          >
            <Download className="h-4 w-4 mr-2" />
            Download PDF
          </Button>
        )}
      </div>
    </motion.div>
  );
}
